import { Kanban, type KanbanCard, type KanbanCardActivateDetail, type KanbanColumn } from '@absoluteui/components/kanban';

const columns: KanbanColumn[] = [
  { id: 'todo', label: 'To do' },
  { id: 'doing', label: 'In progress', wipLimit: 3 },
  { id: 'done', label: 'Done' },
];
const cards: KanbanCard[] = [
  { id: 'a', columnId: 'todo', title: 'Write the spec', tags: ['docs'] },
  { id: 'b', columnId: 'doing', title: 'Fix login', description: 'Safari only', color: 3 },
];

const host = document.createElement('div');
document.body.append(host);
Kanban.create(host, { label: 'Sprint 12', columns, cards });
host.addEventListener('aui-card-activate', (event) => {
  host.dataset.open = (event as CustomEvent<KanbanCardActivateDetail>).detail.card.title;
});

import { Kanban, type KanbanCard, type KanbanMoveErrorDetail } from '@absoluteui/components/kanban';

const host = document.querySelector<HTMLElement>('#board');
if (host) {
  const cards: KanbanCard[] = [{ id: '42', columnId: 'new', title: 'Refund request' }];
  Kanban.create(host, {
    label: 'Support tickets',
    columns: [{ id: 'new', label: 'New' }, { id: 'open', label: 'Open', wipLimit: 10 }, { id: 'closed', label: 'Closed' }],
    cards,
    wipPolicy: 'block',
    requestTimeoutMs: 10_000,
    moveCard: async (move, signal) => {
      const response = await fetch(`/api/tickets/${encodeURIComponent(move.id)}/position`, {
        method: 'PUT',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ column: move.to.columnId, index: move.to.index }),
        signal,
      });
      if (!response.ok) throw new Error(`Move failed: ${String(response.status)}`);
    },
  });
  host.addEventListener('aui-move-error', (event) => {
    host.dataset.failed = (event as CustomEvent<KanbanMoveErrorDetail>).detail.id;
  });
}

import { Kanban, type KanbanCardMoveDetail } from '@absoluteui/components/kanban';

const host = document.createElement('div');
document.body.append(host);
const board = Kanban.create(host, {
  label: 'Releases',
  columns: [{ id: 'dev', label: 'Development' }, { id: 'qa', label: 'QA' }, { id: 'live', label: 'Live', locked: true }],
  lanes: [{ id: 'web', label: 'Web' }, { id: 'app', label: 'Mobile app' }],
  cards: [
    { id: 'w1', columnId: 'dev', laneId: 'web', title: 'New header' },
    { id: 'm1', columnId: 'qa', laneId: 'app', title: 'Push notifications' },
  ],
  // Cards stay in their swimlane.
  canMove: (card, to) => to.laneId === card.laneId,
});
host.addEventListener('aui-card-move', (event) => {
  const { to } = (event as CustomEvent<KanbanCardMoveDetail>).detail;
  if (to.columnId === 'qa' && !window.confirm('Send to QA?')) event.preventDefault();
});
board.setCollapsed('lane', 'app', true);

import { Kanban } from '@absoluteui/components/kanban';

const host = document.createElement('div');
document.body.append(host);
Kanban.create(host, {
  label: 'Hiring',
  columns: [{ id: 'applied', label: 'Applied' }, { id: 'interview', label: 'Interview' }],
  cards: [{ id: 'c1', columnId: 'applied', title: 'Jordan Blake', description: 'Frontend engineer' }],
  // Non-interactive content only: the card itself is the focusable item.
  renderCard: (card, { column, doc }) => {
    const name = doc.createElement('strong');
    name.textContent = card.title;
    const meta = doc.createElement('span');
    meta.textContent = `, ${card.description ?? ''} (${column.label})`;
    const box = doc.createElement('span');
    box.append(name, meta);
    return box;
  },
});

import { columnCounts, moveKanbanCard, positionOf, type KanbanCard } from '@absoluteui/components/kanban';

const cards: KanbanCard[] = [
  { id: 'a', columnId: 'todo', title: 'A' },
  { id: 'b', columnId: 'todo', title: 'B' },
];
const next = moveKanbanCard(cards, 'b', { columnId: 'done', laneId: null, index: 0 });
const where = positionOf(next, 'b', false);
document.body.dataset.done = String(columnCounts(next).get('done') ?? 0) + (where ? ` at ${String(where.index)}` : '');
